mapper.select:
SELECT 'waitSubmit' AS tabFlag, '待提交' AS tabFlagName, count(1) AS count FROM kol_b2c_application kba WHERE kba.is_deleted=FALSE AND kba.approve_status = 'waitSubmit'
${params.permissionSql}
UNION ALL SELECT 'approveIng' AS tabFlag, '待我审核' AS tabFlagName, COUNT ( 1 ) AS COUNT FROM kol_b2c_application kba WHERE kba.is_deleted=FALSE AND kba.approve_status = 'approveIng'
and kba.id in
#{id}
${params.permissionSql}
UNION ALL SELECT 'waitShipped' AS tabFlag, '待发货' AS tabFlagName, count(1) AS count FROM kol_b2c_application kba inner join kol_sub_b2c_application ksba on kba.id = ksba.source_id and ksba.is_deleted = false WHERE kba.is_deleted=FALSE AND kba.approve_status = 'approve'
${params.permissionSql}
UNION ALL SELECT 'shipped' AS tabFlag, '已发货' AS tabFlagName, count(1) AS count FROM kol_b2c_application kba inner join kol_sub_b2c_application ksba on kba.id = ksba.source_id and ksba.is_deleted = false WHERE kba.is_deleted=FALSE AND kba.approve_status = 'approve'
${params.permissionSql}
UNION ALL SELECT 'reject' AS tabFlag, '不通过' AS tabFlagName, count(1) AS count FROM kol_b2c_application kba WHERE kba.is_deleted=FALSE AND kba.approve_status = 'reject'
${params.permissionSql}

select kba.id, kba.approve_status, kbad.id as detailId, kba.code , kbad.sku_id, kbad.sku_no, kbad.partner_id, kbad.nickname, kbad.apply_qty from kol_b2c_application kba inner join kol_b2c_application_detail kbad on kba.id = kbad.main_id and kbad.is_deleted = false where kba.is_deleted = false and kba.invalid_status = false
kbad.id in
#{item}
